from collections import deque

class Queue:
    """基于 deque 的队列实现。"""
    def __init__(self):
        self._data = deque()

    def enqueue(self, x):
        self._data.append(x)

    def dequeue(self):
        return self._data.popleft()

    def front(self):
        return self._data[0]

    def empty(self):
        return len(self._data) == 0

    def size(self):
        return len(self._data)


def bfs(adj, start, n):
    """广度优先搜索: 从 start 出发, 返回各节点到 start 的最短距离。
    adj: 邻接表(0-indexed), n: 节点数
    """
    dist = [-1] * n
    q = Queue()
    q.enqueue(start)
    dist[start] = 0
    while not q.empty():
        u = q.dequeue()
        for v in adj[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                q.enqueue(v)
    return dist


def topo_sort(adj, indeg, n):
    """拓扑排序(Kahn算法): 返回拓扑序, 若有环返回空列表。
    adj: 邻接表, indeg: 入度数组, n: 节点数
    """
    q = Queue()
    for i in range(n):
        if indeg[i] == 0:
            q.enqueue(i)
    order = []
    while not q.empty():
        u = q.dequeue()
        order.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                q.enqueue(v)
    return order if len(order) == n else []


if __name__ == '__main__':
    # 测试队列基本操作
    q = Queue()
    for i in range(5):
        q.enqueue(i)
    print(f'Queue size: {q.size()}')  # 5
    print(f'Front: {q.front()}')  # 0
    while not q.empty():
        print(q.dequeue(), end=' ')  # 0 1 2 3 4 (FIFO)
    print()

    # 测试BFS
    # 图: 0-1, 0-2, 1-3, 2-3, 3-4
    adj = [[1, 2], [3], [3], [4], []]
    dist = bfs(adj, 0, 5)
    print(f'BFS dist from 0: {dist}')  # [0, 1, 1, 2, 3]
    assert dist == [0, 1, 1, 2, 3]

    # 测试拓扑排序
    # DAG: 0->1, 0->2, 1->3, 2->3, 3->4
    adj2 = [[1, 2], [3], [3], [4], []]
    indeg = [0, 1, 1, 2, 1]
    order = topo_sort(adj2, indeg[:], 5)
    print(f'Topo order: {order}')  # [0, 1, 2, 3, 4]
    assert len(order) == 5
    print('All tests passed!')
